def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid center line separates two equal panels.
    divider = next((c for c in range(w)
                    if all(row[c] == grid[0][c] for row in grid)
                    and c == w - 1 - c), None)
    if divider is not None:
        left = [row[:divider] for row in grid]
        right = [row[divider + 1:] for row in grid]
    else:
        divider = next((c for c in range(w)
                        if all(row[c] == grid[0][c] for row in grid)
                        and c == (w - 1) // 2), None)
        if divider is None:
            raise ValueError("no centered solid vertical divider")
        left = [row[:divider] for row in grid]
        right = [row[divider + 1:] for row in grid]
    if not left or len(left[0]) != len(right[0]):
        raise ValueError("divider does not split equal panels")
    shared = set(v for row in left for v in row) & set(v for row in right for v in row)
    if len(shared) != 1:
        raise ValueError(f"expected one shared background color, found {shared}")
    background = next(iter(shared))
    return [[3 if left[r][c] == background and right[r][c] == background else background
             for c in range(len(left[0]))] for r in range(h)]

